    {"name": "Icemon", "types": ["ice", "rock"], "role": "physical", "stage": "Child",
     "abilities": ["icebody", "h:sturdy"],
     "entry": "A little golem of ice blocks. It grins wide as it throws snowballs hard as stone."},
